package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues2D_removeColumn_TriageGen1Test {

    private DefaultKeyedValues2D dataset;

    @Before
    public void setUp() {
        dataset = new DefaultKeyedValues2D();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testRemoveColumn_NullKey() {
        dataset.removeColumn(null);
    }

    @Test
    public void testRemoveColumn_Success() {
        // Arrange
        Comparable row1 = "Row1";
        Comparable row2 = "Row2";
        Comparable col1 = "Col1";
        Comparable col2 = "Col2";

        dataset.addValue(10.0, row1, col1);
        dataset.addValue(20.0, row1, col2);
        dataset.addValue(30.0, row2, col1);
        dataset.addValue(40.0, row2, col2);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals(2, dataset.getRowCount());
        assertEquals(10.0, dataset.getValue(row1, col1).doubleValue(), 0.001);

        // Act
        dataset.removeColumn(col1);

        // Assert
        // Column count should decrease
        assertEquals(1, dataset.getColumnCount());
        // The remaining column should be col2
        assertEquals(col2, dataset.getColumnKeys().get(0));
        // Values associated with col1 should be gone
        assertNull(dataset.getValue(row1, col1));
        assertNull(dataset.getValue(row2, col1));
        // Values associated with col2 should remain
        assertEquals(20.0, dataset.getValue(row1, col2).doubleValue(), 0.001);
        assertEquals(40.0, dataset.getValue(row2, col2).doubleValue(), 0.001);
    }

    @Test
    public void testRemoveColumn_NonExistentKey() {
        // Arrange
        dataset.addValue(10.0, "R1", "C1");

        // Act
        dataset.removeColumn("NonExistent");

        // Assert
        // Nothing should change if key doesn't exist in columnKeys or rows
        assertEquals(1, dataset.getColumnCount());
        assertEquals(10.0, dataset.getValue("R1", "C1").doubleValue(), 0.001);
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Act
        dataset.removeColumn("AnyKey");

        // Assert
        assertEquals(0, dataset.getColumnCount());
        assertEquals(0, dataset.getRowCount());
    }

    @Test
    public void testRemoveColumn_RowWithoutColumn() {
        // Arrange
        // Add a row but don't add the specific column key to it 
        // (Simulating a scenario where rowData.getIndex(columnKey) returns -1)
        Comparable row1 = "Row1";
        Comparable col1 = "Col1";
        Comparable col2 = "Col2";

        dataset.addValue(10.0, row1, col1);
        // We add col2 to the dataset, but we don't add it to row1 specifically
        // However, in DefaultKeyedValues2D, adding a value adds the column key to the dataset.
        // To trigger the (index >= 0) branch logic, we ensure the column exists in the dataset 
        // but the specific row doesn't contain it.

        // Note: In DefaultKeyedValues2D, if a column is in columnKeys, 
        // it's usually expected to be in the rows, but the logic handles the index < 0 case.

        // Act
        dataset.removeColumn(col2);

        // Assert
        assertEquals(1, dataset.getColumnCount());
        assertEquals(col1, dataset.getColumnKeys().get(0));
    }
}
